<!-- Inline Micro-interactions Script -->
<script>
    function togglePasswordVisibility(fieldId, btn) {
      const input = document.getElementById(fieldId);
      const icon = btn.querySelector('.material-symbols-outlined');
      if (input.type === 'password') {
        input.type = 'text';
        icon.textContent = 'visibility_off';
      } else {
        input.type = 'password';
        icon.textContent = 'visibility';
      }
    }

    function checkPasswordStrength(val) {
      const b1 = document.getElementById('bar-1');
      const b2 = document.getElementById('bar-2');
      const b3 = document.getElementById('bar-3');
      const label = document.getElementById('strength-label');

      b1.className = 'h-full w-1/3 rounded-full transition-all bg-outline-variant/40';
      b2.className = 'h-full w-1/3 rounded-full transition-all bg-outline-variant/40';
      b3.className = 'h-full w-1/3 rounded-full transition-all bg-outline-variant/40';

      if (!val) {
        label.textContent = 'Belum diisi';
        label.className = 'font-label-sm text-label-sm text-outline';
        return;
      }

      const hasLength = val.length >= 8;
      const hasNumber = /\d/.test(val);
      const hasLetter = /[a-zA-Z]/.test(val);
      const hasSpecial = /[^a-zA-Z0-9]/.test(val);

      let score = 0;
      if (hasLength) score++;
      if (hasNumber && hasLetter) score++;
      if (hasSpecial && score === 2) score++;

      if (score === 1) {
        b1.classList.replace('bg-outline-variant/40', 'bg-error');
        label.textContent = 'Lemah';
        label.className = 'font-label-sm text-label-sm text-error';
      } else if (score === 2) {
        b1.classList.replace('bg-outline-variant/40', 'bg-tertiary');
        b2.classList.replace('bg-outline-variant/40', 'bg-tertiary');
        label.textContent = 'Cukup Baik';
        label.className = 'font-label-sm text-label-sm text-tertiary';
      } else if (score >= 3) {
        b1.classList.replace('bg-outline-variant/40', 'bg-primary');
        b2.classList.replace('bg-outline-variant/40', 'bg-primary');
        b3.classList.replace('bg-outline-variant/40', 'bg-primary');
        label.textContent = 'Sangat Kuat';
        label.className = 'font-label-sm text-label-sm text-primary';
      }
    }

    function checkPasswordMatch() {
      const pass = document.getElementById('password').value;
      const confirm = document.getElementById('confirm_password').value;
      const confirmInput = document.getElementById('confirm_password');
      if (confirm && pass !== confirm) {
        confirmInput.classList.add('ring-1', 'ring-error');
      } else {
        confirmInput.classList.remove('ring-1', 'ring-error');
      }
    }

    function toggleSport(button, sportKey) {
      const checkIcon = button.querySelector('.material-symbols-outlined');
      const isSelected = button.classList.contains('bg-primary-container');

      if (isSelected) {
        button.classList.remove('bg-primary-container', 'text-on-primary-container');
        button.classList.add('bg-surface-container-high', 'text-on-surface-variant');
        if (checkIcon) checkIcon.classList.add('hidden');
      } else {
        button.classList.remove('bg-surface-container-high', 'text-on-surface-variant');
        button.classList.add('bg-primary-container', 'text-on-primary-container');
        if (checkIcon) checkIcon.classList.remove('hidden');
      }
    }

    function handleRegistration() {
      const pass = document.getElementById('password').value;
      const confirm = document.getElementById('confirm_password').value;
      if (pass !== confirm) {
        alert('Kata sandi dan konfirmasi kata sandi tidak cocok!');
        return;
      }
      alert('Pendaftaran berhasil! Kode OTP verifikasi telah dikirim ke WhatsApp Anda.');
    }
  </script>
